const rows = $input.all().map(i => i.json).filter(r => r.closePrice).sort((a, b) => a.localDate.localeCompare(b.localDate));
const today = DateTime.now().setZone('Asia/Seoul').toFormat('yyyyMMdd');
const last = rows[rows.length - 1];
// 휴장일(오늘 봉 없음)이면 알림 생략
if (!last || last.localDate !== today) return [];

const info = {};
for (const t of $('Fetch Fundamentals').first().json.totalInfos || []) info[t.code] = t.value;
const num = s => Number(String(s ?? '').replace(/[^0-9.\-]/g, ''));

const closes = rows.map(r => r.closePrice);
const vols = rows.map(r => r.accumulatedTradingVolume);
const sma = (arr, n) => arr.length >= n ? arr.slice(-n).reduce((a, b) => a + b, 0) / n : null;

const close = last.closePrice;
const prev = num(info.lastClosePrice) || rows[rows.length - 2]?.closePrice || close;
const chg = close - prev;
const chgPct = prev ? (chg / prev) * 100 : 0;

const ma5 = sma(closes, 5), ma20 = sma(closes, 20), ma60 = sma(closes, 60);
const pc = closes.slice(0, -1);
const pma5 = sma(pc, 5), pma20 = sma(pc, 20);

// RSI(14, Wilder)
let rsi = null;
if (closes.length > 14) {
  let g = 0, l = 0;
  for (let i = 1; i <= 14; i++) { const d = closes[i] - closes[i - 1]; d >= 0 ? g += d : l -= d; }
  g /= 14; l /= 14;
  for (let i = 15; i < closes.length; i++) {
    const d = closes[i] - closes[i - 1];
    g = (g * 13 + Math.max(d, 0)) / 14;
    l = (l * 13 + Math.max(-d, 0)) / 14;
  }
  rsi = l === 0 ? 100 : 100 - 100 / (1 + g / l);
}

const avgVol20 = sma(vols.slice(0, -1), 20);
const volRatio = avgVol20 ? last.accumulatedTradingVolume / avgVol20 : null;
const hi52 = num(info.highPriceOf52Weeks), lo52 = num(info.lowPriceOf52Weeks);

const signals = [];
if (ma5 && ma20 && pma5 && pma20) {
  if (pma5 <= pma20 && ma5 > ma20) signals.push('🟢 골든크로스 (MA5가 MA20 상향 돌파)');
  if (pma5 >= pma20 && ma5 < ma20) signals.push('🔴 데드크로스 (MA5가 MA20 하향 이탈)');
}
if (rsi !== null) {
  if (rsi >= 70) signals.push('🔥 RSI 과매수 구간 (' + rsi.toFixed(1) + ')');
  else if (rsi <= 30) signals.push('🧊 RSI 과매도 구간 (' + rsi.toFixed(1) + ')');
}
if (volRatio && volRatio >= 2) signals.push('📢 거래량 급증 (20일 평균 대비 ' + volRatio.toFixed(1) + '배)');
if (Math.abs(chgPct) >= 5) signals.push((chgPct > 0 ? '🚀 급등 ' : '⚠️ 급락 ') + chgPct.toFixed(2) + '%');
if (lo52 && close <= lo52 * 1.05) signals.push('📉 52주 최저가 근접 (' + lo52.toLocaleString('ko-KR') + '원)');
if (hi52 && close >= hi52 * 0.95) signals.push('📈 52주 최고가 근접 (' + hi52.toLocaleString('ko-KR') + '원)');

let trend = '판단 보류(데이터 부족)';
if (ma20 && ma60) trend = close > ma20 && ma20 > ma60 ? '상승 추세 (정배열)' : close < ma20 && ma20 < ma60 ? '하락 추세 (역배열)' : '혼조 / 횡보';

const f = (n, d = 0) => n === null || n === undefined ? '-' : Number(n).toLocaleString('ko-KR', { maximumFractionDigits: d });
const arrow = chg > 0 ? '▲' : chg < 0 ? '▼' : '-';
const head = chg > 0 ? '📈' : chg < 0 ? '📉' : '➖';

const message = [
  head + ' *PKC (001340) 장마감 분석* · ' + DateTime.now().setZone('Asia/Seoul').toFormat('yyyy-MM-dd'),
  '*종가* ' + f(close) + '원  ' + arrow + ' ' + f(Math.abs(chg)) + '원 (' + (chgPct >= 0 ? '+' : '') + chgPct.toFixed(2) + '%)',
  '시/고/저  ' + f(last.openPrice) + ' / ' + f(last.highPrice) + ' / ' + f(last.lowPrice) + '  |  거래량 ' + f(last.accumulatedTradingVolume) + (volRatio ? ' (20일 평균 ' + volRatio.toFixed(1) + '배)' : ''),
  '',
  '*추세*  ' + trend,
  'MA5 ' + f(ma5) + '  ·  MA20 ' + f(ma20) + '  ·  MA60 ' + f(ma60) + '  ·  RSI(14) ' + (rsi === null ? '-' : rsi.toFixed(1)),
  '*밸류에이션*  PER ' + (info.per || '-') + '  ·  PBR ' + (info.pbr || '-') + '  ·  시총 ' + (info.marketValue || '-') + '  ·  배당수익률 ' + (info.dividendYieldRatio || '-'),
  '52주 범위  ' + (info.lowPriceOf52Weeks || '-') + ' ~ ' + (info.highPriceOf52Weeks || '-'),
  '',
  '*시그널*',
  signals.length ? signals.map(s => '• ' + s).join('\n') : '• 특이 시그널 없음',
  '',
  '_자동 생성된 기술적 지표 요약이며 투자 권유가 아닙니다._'
].join('\n');

return [{ json: { message, close, chgPct, rsi, ma5, ma20, ma60, signals } }];
